INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `description`, `ingredients`, `nutritional_info`, `weight`, `shelf_life`, `storage_instructions`, `image`, `bg_color`, `price`, `original_price`, `discount_percentage`, `stock`, `sku`, `is_active`, `is_featured`, `is_new`, `is_vegetarian`, `country_of_origin`, `created_at`, `updated_at`) VALUES
(16, 3, '3x APPLE', '3-pack-apple', 'Three packs of our crisp and sweet dehydrated Kashmiri apples. Light, healthy, and naturally sweet.', '[\"Apple\"]', '{\"Per 100 g\":\"\",\"Energy\":\"250 kcal\",\"Protein\":\"1.5 g\",\"Carbohydrate\":\"67 g\",\"Total Sugars\":\"58 g\",\"Total Fat\":\"0.5 g\",\"Dietary Fiber\":\"8.2 g\",\"Sodium\":\"4 mg\"}', '0.045', '6 months', '0', 'assets/images/products/prod_698dcea092b52.jpeg', '', 169.00, 360.00, 0, 15, NULL, 1, 1, 0, 1, '0', '2026-01-17 14:47:53', '2026-03-02 16:33:29'),
(17, 3, '3x BANANA', '3-pack-banana', 'Triple the goodness of our soft and chewy dehydrated bananas. No added sugar, just pure fruit energy.', '[\"Banana\"]', '{\"Per 100 g\":\"\",\"Energy\":\"310 kcal\",\"Protein\":\"3.2 g\",\"Carbohydrate\":\"80 g\",\"Total Sugars\":\"43 g\",\"Total Fat\":\"1.0 g\",\"Dietary Fiber\":\"8.3 g\",\"Sodium\":\"4 mg\"}', '0.090', '6 months', '0', 'assets/images/products/prod_698dce895985f.jpeg', '', 220.00, 360.00, 0, 15, NULL, 1, 1, 0, 1, '0', '2026-01-17 14:47:53', '2026-03-02 16:33:10'),
(18, 3, 'Fruit Trio Mix (Apple + Banana + Kiwi)', '3-pack-mix', 'Taste the full range with one pack each of our Apple Rings, Banana Coins, and Kiwi Slices. The ultimate fruit snack variety.', '[\"Apple\",\"Banana\",\"Kiwi\"]', '{\"Per 100 g (Avg)\":\"\",\"Energy\":\"293 kcal\",\"Protein\":\"2.6 g\",\"Carbohydrate\":\"74 g\",\"Dietary Fiber\":\"10.3 g\",\"Sodium\":\"5 mg\"}', '0.070', '6 months', '0', 'assets/images/products/prod_698dcf05cdbd3.jpeg', '', 239.00, 250.00, 0, 13, NULL, 1, 1, 0, 1, '0', '2026-01-17 14:47:53', '2026-03-02 16:33:40'),
(20, 3, 'The Grand Driyum Experience Hamper', 'grand-hamper', 'The complete collection of Driyum\'s finest. Includes Banana, Apple, Kiwi, Alle hachi, and Wangan hachi. A perfect gift for health enthusiasts.', '[\"Banana\",\"Apple\",\"Kiwi\",\"Alle hachi\",\"Wangan hachi\"]', '{\"Variety Pack\":\"Multiple\"}', '0.57', '6 months', '0', 'assets/images/products/prod_696bbe13eb874.webp', '#F0FDFA', 849.00, 1150.00, 0, 0, NULL, 0, 0, 0, 1, '0', '2026-01-17 14:47:53', '2026-02-12 12:00:23'),
(21, 1, 'Banana', 'banana', 'Driyum Banana is made from carefully selected ripe bananas, gently dehydrated to lock in their natural sweetness and texture. Soft, chewy, and naturally satisfyingâ€”this is banana in its purest, most convenient form. No added sugar, no additives, just real fruit.', '[\"Banana\"]', '{\"Per 100 g\":\"\",\"Energy\":\"310 kcal\",\"Protein\":\"3.2 g\",\"Carbohydrate\":\"80 g\",\"Total Sugars\":\"43 g\",\"Total Fat\":\"1.0 g\",\"Dietary Fiber\":\"8.3 g\",\"Sodium\":\"4 mg\"}', '0.030', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_698dcaf846824.jpeg', '', 80.00, 120.00, 0, 15, NULL, 1, 0, 0, 1, 'India', '2026-02-11 15:48:12', '2026-03-02 16:33:34'),
(22, 1, 'Apple', 'apple', 'Driyum Apple is made from carefully selected apples, gently dehydrated to preserve their natural sweetness and crisp fruit character. Lightly chewy, subtly sweet, and refreshingâ€”just real apple, with nothing added.', '[\"Apple\"]', '{\"Per 100 g\":\"\",\"Energy\":\"250 kcal\",\"Protein\":\"1.5 g\",\"Carbohydrate\":\"67 g\",\"Total Sugars\":\"58 g\",\"Total Fat\":\"0.5 g\",\"Dietary Fiber\":\"8.2 g\",\"Sodium\":\"4 mg\"}', '0.015', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_698dcc72bb315.jpeg', '', 69.00, 120.00, 0, 15, NULL, 1, 0, 0, 1, 'India', '2026-02-11 15:48:12', '2026-03-02 16:33:24'),
(23, 1, 'Kiwi', 'kiwi', 'Driyum Kiwi is bright, tangy, and naturally refreshing. Dehydrated from ripe kiwis, it delivers a bold balance of sweet and tart with a soft chew that wakes up your palate. A fruit snack with real characterâ€”nothing added, nothing hidden.', '[\"Kiwi\"]', '{\"Per 100 g\":\"\",\"Energy\":\"320 kcal\",\"Protein\":\"3.1 g\",\"Carbohydrate\":\"75 g\",\"Total Sugars\":\"46 g\",\"Total Fat\":\"1.1 g\",\"Dietary Fiber\":\"14.5 g\",\"Sodium\":\"6 mg\"}', '0.025', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_698dcc9a81ca8.jpeg', '', 125.00, 160.00, 0, 15, NULL, 1, 0, 0, 1, 'India', '2026-02-11 15:48:12', '2026-03-02 16:33:04'),
(25, 5, 'Alle hachi (200g)', 'alle-hachi', 'Alle hachi have a mild, subtle flavour that blends effortlessly into cooked dishes. Traditionally sun-dried, it softens on cooking and absorbs spices beautifully, making it ideal for light curries, rice-based meals, and slow-cooked dishes. Naturally light and fibre-rich, it adds balance without overpowering the dish.', '[\"Sun-dried Bottle Gourd\"]', '{\"Per 100 g\":\"\",\"Energy\":\"320 kcal\",\"Total Carbohydrate\":\"73 g\",\"Total Sugars\":\"32 g\",\"Dietary Fibre\":\"14 g\",\"Protein\":\"13 g\",\"Total Fat\":\"2.5 g\",\"Saturated Fat\":\"0.5 g\",\"Trans Fat\":\"0 g\",\"Sodium\":\"50 mg\"}', '0.200', 'Best before 6 months from the date of packaging.', 'Store in cool and dry place.', 'assets/images/products/prod_698db87659598.jpeg', '', 249.00, 349.00, 0, 5, NULL, 1, 1, 0, 1, 'India', '2026-02-11 16:15:27', '2026-02-24 10:21:59'),
(26, 5, 'Wangan hachi (100g)', 'wangan-hachi', 'Wangan hachi develop a deeper, earthy flavour when cooked. Sun-dried and rehydrated during cooking, it absorbs spices and gravies well, adding body and richness to curries and rice dishes. Naturally high in fibre, it is best enjoyed in slow-cooked or spice-forward preparations.', '[\"Sun-dried Eggplant (Brinjal)\"]', '{\"Per 100 g\":\"\",\"Energy\":\"310 kcal\",\"Total Carbohydrate\":\"68 g\",\"Total Sugars\":\"28 g\",\"Dietary Fibre\":\"22 g\",\"Protein\":\"14 g\",\"Total Fat\":\"2.5 g\",\"Saturated Fat\":\"0.6 g\",\"Trans Fat\":\"0 g\",\"Sodium\":\"30 mg\"}', '0.100', '6 months', 'Store in cool and dry place.', 'assets/images/products/prod_698db812bff88.jpeg', '', 120.00, 200.00, 0, 2, NULL, 1, 1, 0, 1, 'India', '2026-02-11 16:15:27', '2026-02-24 10:22:00'),
(27, 3, '3x KIWI', '3-pack-kiwi-slices', 'A trio of our premium tangy and refreshing dehydrated Kiwi slices. Perfect for stocking up on your favorite tart treat.', '[\"Kiwi\"]', '{\"Per 100 g\":\"\",\"Energy\":\"320 kcal\",\"Protein\":\"3.1 g\",\"Carbohydrate\":\"75 g\",\"Total Sugars\":\"46 g\",\"Total Fat\":\"1.1 g\",\"Dietary Fiber\":\"14.5 g\",\"Sodium\":\"6 mg\"}', '0.075', '6 months', 'Store in cool and dry place.', 'assets/images/products/prod_698dce570f3af.jpeg', '', 320.00, 480.00, 0, 15, NULL, 1, 1, 0, 1, 'India', '2026-02-11 16:54:18', '2026-03-02 16:33:16'),
(28, 3, 'Kashmiri Hokh Suin Combo ', 'kashmiri-hokh-suin-combo-alle-wangan-', 'A traditional pairing of sun-dried Alle hachi [Bottle Gourd]200g ,Wangan hachi [Brinjal]100g and Ruwangan Hachi [ Tomato]150g . Perfect for authentic Kashmiri curries.', '[\"Sun-dried Bottle Gourd\",\"Sun-dried Brinjal\",\"Sun Dried Tomatoes\"]', '{\"Energy\":\"\",\"Protein\":\"\",\"Carbohydrates\":\"\",\"Total Sugars\":\"\",\"Total Fat\":\"\",\"Dietary Fiber\":\"\",\"Sodium\":\"\"}', '0.450', '6 months', 'Store in cool and dry place.', 'assets/images/products/prod_698dcec9575b8.jpeg', '', 550.00, 800.00, 0, 2, NULL, 1, 0, 0, 1, 'India', '2026-02-11 16:54:18', '2026-02-24 10:23:06'),
(100, 5, 'Ruwangan Hachi (150g)', 'ruwangan-hachi', '', '[]', '{\"Energy\":\"260KCal\",\"Protein\":\"13g\",\"Carbohydrates\":\"58g\",\"Total Sugars\":\"38g\",\"Total Fat\":\"3,5g\",\"Dietary Fiber\":\"12g\",\"Sodium\":\"75mg\"}', '0.150', NULL, NULL, 'assets/images/products/prod_698dd17c4ded8.jpeg', '', 199.00, 249.00, 0, 0, NULL, 1, 0, 0, 1, 'India', '2026-02-12 11:34:26', '2026-03-01 11:25:03'),
(101, 1, 'Fig Rolls', 'fig-rolls', 'Driyum Fig rolls: These are naturally sweetened fig rolls with 80% fig and 20% jaggery, a great healthy alternative for candies.\r\nFigs are rich source of dietary fiber, rich in iron , calcium and also helps to increase hemoglobin levels and helps lower your cholesterol,', '[\"FIG\",\"Jaggery\",\"citric acid\"]', '{\"Energy\":\"\",\"Protein\":\"\",\"Carbohydrates\":\"\",\"Total Sugars\":\"\",\"Total Fat\":\"\",\"Dietary Fiber\":\"\",\"Sodium\":\"\",\"protein\":\"2.18\",\"Fat\":\"0\",\"energy\":\"129\",\"fiber\":\"3.07\",\"calcium\":\"38.16mg\",\"Iron\":\"14.64mg\"}', '0.250', NULL, NULL, 'assets/images/products/prod_69a051682e872.jpeg', '', 300.00, 400.00, 0, 11, NULL, 1, 0, 0, 1, 'India', '2026-02-26 13:58:00', '2026-03-02 16:32:57');
