INSERT INTO `settings` (`key`, `value`, `updated_at`) VALUES
('about_hero_desc', 'We\'re on a mission to prove that healthy snacking shouldn\'t cost the earth or your health.', '2026-02-02 06:01:08'),
('about_hero_subtitle', 'The Driyum Journeys', '2026-02-02 06:01:08'),
('about_hero_title', 'Born from <span class=\"text-[#19DC7E]\">Frustration</span>,<br>Dried to <span class=\"text-amber-500\">Perfection</span>.', '2026-02-02 06:01:08'),
('about_mission', 'Our mission is to make healthy snacking affordable, accessible, and convenient for everyone.', '2026-02-02 06:01:08'),
('about_story_quote', '\"We simply select the best fruit and gently dehydrate it. That\'s it!\"', '2026-02-02 06:01:08'),
('about_story_text', 'Our whole journey started with a simple frustration: why were all the truly healthy snacks so expensive, while the cheap ones were loaded with processed ingredients?\r\n\r\nIt felt like we were filling our bodies with chemical experiments and guilt rather than a snack. We realized the market was missing something. So, we took matters into our own hands, deciding to create the perfect alternative.', '2026-02-02 06:01:08'),
('about_story_title', 'The \"Aha!\" Moment', '2026-02-02 06:01:08'),
('about_tip_text', 'In dried form, the vegetables may feel hard or chewy, which is natural. Once soaked or cooked, they soften and become ready for use in rice dishes, curries, and traditional meals. It is not just dehydrated vegetables â€” it is a piece of Kashmiri heritage, thoughtfully prepared and delivered to your doorstep.', '2026-02-02 06:01:08'),
('about_tip_title', 'A Quick Tip for the Perfect Meal', '2026-02-02 06:01:08'),
('about_tradition_text', 'With long, harsh winters and limited access to fresh produce, families would preserve vegetables during summer so the warmth and flavour of the season could be carried into winter meals. What was once an everyday practice has now become a delicacy â€” a way to taste tradition, history, and memory.\r\n\r\nAs modern lifestyles take over, this practice is slowly fading. \"Hokh suin by Driyum\" is our effort to revive this tradition and make it accessible again.', '2026-02-02 06:01:08'),
('about_tradition_title', 'HOKH SUIN', '2026-02-02 06:01:08'),
('about_twist_text', 'Prepared from fresh vegetables, Hokh suin is traditionally premium, but unlike earlier times, it is handled with modern hygiene standards and packed carefully to ensure safety, quality, and convenience.', '2026-02-05 12:08:36'),
('about_twist_title', 'Modern Twist on Ancient Traditions', '2026-02-02 06:01:08'),
('about_vision', 'To build Driyum into one of Indiaâ€™s leading healthy snacking brands, starting from Kashmir and reaching across the country.', '2026-02-02 06:01:08'),
('announcement_bg_color', '#016048', '2026-02-12 09:54:09'),
('announcement_text', 'ðŸŽFREE SHIPPING ON ORDERS ABOVE 1000  ðŸŒ', '2026-02-12 12:55:09'),
('backup_frequency', 'manual', '2026-02-12 13:32:48'),
('facebook_url', '', '2026-02-05 13:06:57'),
('footer_description', 'Redefining the art of snacking with premium, indulgence. Naturally sweet, unapologetically bold', '2026-02-02 06:06:41'),
('free_shipping_threshold', '1000', '2026-02-12 12:08:01'),
('instagram_url', 'https://www.instagram.com/driyumfoods?utm_source=ig_web_button_share_sheet&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;igsh=ZDNlZDc0MzIxNw%3D%3D', '2026-02-13 16:16:58'),
('last_backup_at', '19 Feb 2026, 07:34 PM', '2026-02-19 14:04:13'),
('last_cron_run', '1772544740', '2026-03-03 13:32:20'),
('legal_disclaimer', 'Driyum products are made using natural fruits and vegetables. As these are agricultural products, variations in colour, taste, texture, and appearance may occur. Nutritional values are approximate. Consult a professional before consumption if you have medical conditions.', '2026-02-02 06:01:08'),
('legal_privacy_policy', 'At Driyum, we value your privacy and are committed to protecting your personal information. When you visit our website or place an order, we may collect basic details such as your name, phone number, email address, delivery address, and payment-related information.\r\n\r\nThis information is collected solely for the purpose of processing orders, providing customer support, and improving our services. We do not sell, rent, or share your personal data with third parties, except where required to complete your order (such as payment gateways and delivery partners) or when required by law.', '2026-02-02 06:01:08'),
('legal_returns_refunds', 'Due to the nature of food products, returns are not accepted once an order has been delivered. Refunds may be considered only in special cases, including damaged packaging or unsealed pouches. To request a refund, customers are required to share a clear unboxing video of the package.', '2026-02-02 06:01:08'),
('legal_terms_conditions', 'By accessing and using the Driyum website, you agree to comply with these terms and conditions.\r\n\r\nAll products sold by Driyum are food products. Dehydrated fruits are intended for direct consumption, while dehydrated vegetables are intended for cooking purposes only. Product images shown on the website are for representation purposes only. Actual product colour, size, and texture may vary due to natural variations in fruits and vegetables.', '2026-02-02 06:01:08'),
